	fmt.Printf("Размер массива:   %d байт (3 строки x 16 байт)\n", unsafe.Sizeof(languages))
}

theory:
**Парадигма Pass by Value для массивов:**
- Функция `SumArray(arr [5]int)` получает **локальную копию массива**;
- Любые мутации внутри функции затрагивают только локальный стековый фрейм;
- Исходный массив вызывающей стороны гарантированно защищен от изменений.

code_blocks.code:
package main

import "fmt"

func SumArray(arr [5]int) int {
	// Мутируем локальную копию:
	arr[0] = 999
	fmt.Printf("   [Внутри SumArray] arr = %v\n", arr)

	total := 0
	for _, v := range arr {
		total += v
	}
	return total
}

func main() {
	original := [5]int{10, 20, 30, 40, 50}

	fmt.Printf("1. До вызова функции:    %v\n", original)
	sum := SumArray(original)
	fmt.Printf("2. Сумма из функции:      %d\n", sum)
	fmt.Printf("3. После вызова функции: %v (НЕ ИЗМЕНИЛСЯ!)\n", original)
}

theory:
**Comparable Semantics (Сравнимость массивов):**
1. Массивы в Go **сравнимы операторами `==` и `!=`**, если их элементы сравнимы;
2. Два массива равны, если равны все их элементы на соответствующих позициях;
3. Массивы `[3]int` и `[4]int` имеют **разные типы данных** $ightarrow$ их прямое сравнение запрещено компилятором на этапе статического анализа (`mismatched types [3]int and [4]int`).

code_blocks.code:
package main

import "fmt"

func main() {
	a := [3]int{1, 2, 3}
	b := [3]int{1, 2, 3}
	c := [3]int{1, 2, 9}

	fmt.Printf("a == b: %t (идентичные элементы)\n", a == b)
	fmt.Printf("a == c: %t (отличаются в c[2])\n", a == c)
	fmt.Printf("a != c: %t\n", a != c)

	// Массив другой длины:
	// d := [4]int{1, 2, 3, 4}
	// fmt.Println(a == d) // ОШИБКА КОМПИЛЯЦИИ: mismatched types [3]int and [4]int
}

package main

import "fmt"

func IsArrayPalindrome(arr [6]int) bool {
	i, j := 0, len(arr)-1
	for i < j {
		if arr[i] != arr[j] {
			return false
		}
		i++
		j--
	}
	return true
}

func main() {
	arr1 := [6]int{1, 2, 3, 3, 2, 1}
	arr2 := [6]int{1, 2, 3, 4, 2, 1}

	fmt.Printf("Массив %v -> Палиндром: %t\n", arr1, IsArrayPalindrome(arr1))
	fmt.Printf("Массив %v -> Палиндром: %t\n", arr2, IsArrayPalindrome(arr2))
}

theory:
**Двумерный массив `[Rows][Cols]T`:**
- Представляет собой **единый непрерывный блок памяти** из $	ext{Rows} 	imes 	ext{Cols}$ элементов;
- `[3][4]int` занимает в памяти ровно $3 	imes 4 	imes 8 = 96$ байт;
- В отличие от среза срезов `[][]int`, двумерный массив не имеет указателей и хранится в кэше процессора максимально компактно.

