theory:
**Выравнивание памяти (Memory Alignment):**
- `unsafe.Sizeof([100]int64)` = $100 	imes 8 = 800$ байт;
- `unsafe.Alignof([100]int64)` = $8$ байт (выравнивание массива совпадает с выравниванием его базового типа `int64`);
- Все элементы идут подряд с шагом 8 байт.

code_blocks.code:
package main

import (
	"fmt"
	"unsafe"
)

func main() {
	var bigArray [100]int64

	fmt.Printf("1. Размер массива:        %d байт\n", unsafe.Sizeof(bigArray))
	fmt.Printf("2. Выравнивание массива:  %d байт\n", unsafe.Alignof(bigArray))
	fmt.Printf("3. Выравнивание элемента: %d байт\n", unsafe.Alignof(bigArray[0]))

	// Проверка шага адресов:
	addr0 := uintptr(unsafe.Pointer(&bigArray[0]))
	addr1 := uintptr(unsafe.Pointer(&bigArray[1]))
	fmt.Printf("4. Шаг между элементами:  %d байт\n", addr1-addr0)
}

theory:
**Почему массивы могут быть ключами в `map`, а срезы нет?**
1. В Go ключом в `map[K]V` может быть **только сравнимый тип (Comparable Type)**, для которого определен оператор `==`;
2. Массивы `[3]int` являются comparable $ightarrow$ их можно использовать как ключи;
3. Срезы `[]int` НЕ являются comparable $ightarrow$ `map[[]int]string` вызовет ошибку компиляции `invalid map key type []int`.

code_blocks.code:
package main

import "fmt"

func main() {
	// Массив [3]int в роли ключа хэш-таблицы (RGB палитра):
	palette := map[[3]int]string{
		{255, 0, 0}:     "Красный",
		{0, 255, 0}:     "Зеленый",
		{0, 0, 255}:     "Синий",
		{255, 255, 255}: "Белый",
		{0, 0, 0}:       "Черный",
	}

	target := [3]int{0, 255, 0}
	if name, ok := palette[target]; ok {
		fmt.Printf("Цвет RGB %v: %s\n", target, name)
	}

	// map[[]int]string // ОШИБКА: invalid map key type []int
}

package main

import "fmt"

func ReverseArrayInPlace(arr *[8]string) {
	for i, j := 0, len(arr)-1; i < j; i, j = i+1, j-1 {
		arr[i], arr[j] = arr[j], arr[i] // Атомарный swap на месте
	}
}

func main() {
	tokens := [8]string{"1", "2", "3", "4", "5", "6", "7", "8"}

	fmt.Printf("До разворота:    %v\n", tokens)
	ReverseArrayInPlace(&tokens)
	fmt.Printf("После разворота: %v\n", tokens)
}

